public record Contract
{
    public required string Customer { get; init; }
    public required string Supplier  { get; init; }
}
// new Contract { Customer = c, Supplier = s } compiles;
// omitting either member is error CS9035; later mutation is rejected.

// Pre-C#-11 fallback: validated factory + restricted construction
public sealed class Contract2
{
    private Contract2(string customer, string supplier) =>
        (Customer, Supplier) = (customer, supplier);
    public string Customer { get; }
    public string Supplier { get; }
    public static Contract2 Create(string customer, string supplier) =>
        string.IsNullOrEmpty(customer) || string.IsNullOrEmpty(supplier)
            ? throw new ArgumentException("customer and supplier are compulsory")
            : new Contract2(customer, supplier);
}

